const fs = require('fs');

const data = fs.readFileSync(0, 'utf8').trim().split(/\s+/).map(Number);
const n = data[0];
const grid = [];
let index = 1;
let zeroRow = 0;
let zeroCol = 0;

for (let r = 0; r < n; r++) {
  grid[r] = data.slice(index, index + n);
  index += n;

  const c = grid[r].indexOf(0);
  if (c !== -1) {
    zeroRow = r;
    zeroCol = c;
  }
}

const magicSum = grid.find(row => !row.includes(0)).reduce((sum, value) => sum + value, 0);
const missingValue = magicSum - grid[zeroRow].reduce((sum, value) => sum + value, 0);

console.log(missingValue);
console.log(zeroRow + 1);
console.log(zeroCol + 1);
